def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, deque

    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    seen = set()
    q = deque()

    for r in range(h):
        for c in range(w):
            if (r in (0, h - 1) or c in (0, w - 1)) and grid[r][c] == bg:
                if (r, c) not in seen:
                    seen.add((r, c))
                    q.append((r, c))

    while q:
        r, c = q.popleft()
        for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == bg and (nr, nc) not in seen:
                seen.add((nr, nc))
                q.append((nr, nc))

    out = [row[:] for row in grid]
    visited = set(seen)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r, c) in visited:
                continue
            comp = set()
            q = deque([(r, c)])
            visited.add((r, c))
            while q:
                cr, cc = q.popleft()
                comp.add((cr, cc))
                for nr, nc in ((cr-1,cc), (cr+1,cc), (cr,cc-1), (cr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == bg and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        q.append((nr, nc))
            height = max(x[0] for x in comp) - min(x[0] for x in comp) + 1
            width = max(x[1] for x in comp) - min(x[1] for x in comp) + 1
            color = 7 if height % 2 and width % 2 else 2
            for cr, cc in comp:
                out[cr][cc] = color
    return out
